export const glossary: Array<[string, string]> = [["Term", "Meaning"], ["HEDIS", "Healthcare Effectiveness Data and Information Set: the quality measures published by NCQA."], ["NCQA", "National Committee for Quality Assurance, the organization that publishes HEDIS."], ["Measurement year", "The calendar year a measure reports on (January 1 to December 31)."], ["ECDS", "Electronic Clinical Data Systems: HEDIS reporting method that uses claims plus electronic clinical data (EHR, registries). Measure names ending in -E use it."], ["Hybrid", "HEDIS reporting method that combines administrative data with medical record review."], ["Administrative data", "Data from claims and enrollment."], ["Supplemental data", "Clinical data from sources other than claims (EHR, registries, labs). Kept apart from administrative data for audit."], ["Continuous enrollment (CE)", "The rule that a member must be enrolled for a set period, with limited gaps, to be counted in a measure."], ["Product line", "Commercial, Exchange, Medicaid or Medicare. Set by Payer in member-en.csv."], ["Stratification", "Reporting a measure result separately for groups of members (for example by race, ethnicity or SES)."], ["RES", "Race and ethnicity stratification."], ["SES", "Socioeconomic status stratification for Medicare members, based on LIS/DE and disability (OREC)."], ["LDM", "Language Diversity of Membership (HEDIS measure)."], ["WCV", "Child and Adolescent Well-Care Visits."], ["BCS-E", "Breast Cancer Screening (ECDS)."], ["CCS-E", "Cervical Cancer Screening (ECDS)."], ["COL-E", "Colorectal Cancer Screening (ECDS)."], ["GSD", "Glycemic Status Assessment for Patients With Diabetes."], ["CIS-E / IMA-E", "Childhood Immunization Status / Immunizations for Adolescents (ECDS)."], ["Other measure codes", "Codes such as AAB, ADD-E, AHU, AXR, COA, COU, DAE, DBO, EDH, EDU, EED, FUA, FUH, FUM, HDO, IET, OED, PCR, SNS-E, TFC, TRC and UOP are other HEDIS measures. They appear only as examples of how a field is used."], ["Hospice", "Member in hospice care. Members in hospice are excluded from most measures."], ["LTI", "Long-term institutional status: the member lives long term in an institution (for example a nursing home)."], ["I-SNP", "Institutional Special Needs Plan (Payer = SN2 in member-en.csv)."], ["SNP", "Special Needs Plan."], ["OREC", "Original Reason for Entitlement Code: why the member first became entitled to Medicare (age, disability, ESRD)."], ["ESRD", "End-stage renal disease."], ["LIS", "Low-income subsidy for Medicare Part D."], ["LIS/DE", "Low-income subsidy or dual eligibility (Medicare and Medicaid)."], ["MMR", "CMS Monthly Membership Report, the source of the hospice, LTI and OREC values."], ["LISHIST", "CMS Low Income Subsidy history file, the source of the low-income subsidy periods."], ["CMS", "Centers for Medicare & Medicaid Services."], ["LTSS", "Long-term services and supports."], ["Professional claim", "Claim billed on a CMS-1500 form or 837P transaction (physician and other practitioner services)."], ["Institutional claim", "Claim billed on a UB-04 form or 837I transaction (hospital and facility services)."], ["Dental claim", "Claim billed on an ADA form or 837D transaction."], ["NCPDP", "National Council for Prescription Drug Programs: the standard for pharmacy claims."], ["UB-04 FL", "A form locator (box) on the UB-04 institutional claim form."], ["Type of Bill", "4-character code on institutional claims for the facility type and the bill frequency."], ["Revenue code", "4-character code on institutional claim lines for the facility service (for example 0450 emergency room)."], ["Place of Service (POS)", "2-character CMS code for where a service was given (for example 11 office, 02 telehealth)."], ["Adjudication", "The payer's decision on a claim: paid, denied or partially paid."], ["Reversal / voided claim", "A claim record that cancels an earlier claim. Do not send these; send the final version of each claim."], ["CPT", "Current Procedural Terminology (Category I procedure codes)."], ["CPT II", "CPT Category II codes, used for results and quality reporting (for example 3044F)."], ["HCPCS", "Healthcare Common Procedure Coding System, Level II."], ["CDT", "Current Dental Terminology (dental procedure codes, D followed by 4 digits)."], ["ICD-10-CM / ICD-9-CM", "International Classification of Diseases diagnosis codes (ICD-9-CM also has procedure codes)."], ["ICD-10-PCS", "ICD-10 Procedure Coding System (inpatient procedures)."], ["SNOMED", "SNOMED CT clinical terminology (US edition)."], ["LOINC", "Logical Observation Identifiers Names and Codes, used for lab tests and observations."], ["NDC", "National Drug Code, 11 digits."], ["RxNorm", "Standard names and codes for clinical drugs."], ["CVX", "CDC vaccine codes."], ["UCUM", "Unified Code for Units of Measure, used for result units (for example %, kg)."], ["BCP-47", "Standard language codes (for example en, es). See the Language Codes tab."], ["CDC Race and Ethnicity", "CDC code system for race and ethnicity. See the Detailed Race & Ethnicity tab."], ["NPI", "National Provider Identifier, 10 digits."], ["NUCC taxonomy", "National Uniform Claim Committee code for a provider's type and specialty (10 characters)."], ["NPPES", "National Plan and Provider Enumeration System, the NPI registry."], ["FHIR", "Fast Healthcare Interoperability Resources: the standard the data is converted to before the measures run."], ["CQL", "Clinical Quality Language: the language NCQA uses to write the measure logic."], ["EHR", "Electronic health record."], ["CSV", "Comma-separated values file."], ["UTF-8", "Standard text encoding for the files."], ["YYYYMMDD", "Date format: 4-digit year, 2-digit month, 2-digit day (for example 20260131)."]];
